    var target = findContactKey(targetName) || findPlayerStatsKey(targetName) || resolvePlayerName(targetName) || targetName;

    var sourceStatsKey = findPlayerStatsKey(sourceName);
    var targetStatsKey = findPlayerStatsKey(target);
